import{_ as a,o as t,c as i,ag as s}from"./chunks/framework.CxkNbRKf.js";const g=JSON.parse('{"title":"Solr search","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/solr.md","filePath":"admin-guide/web-ui/solr.md","lastUpdated":1786379412000}'),o={name:"admin-guide/web-ui/solr.md"};function n(r,e,l,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="solr-search" tabindex="-1">Solr search <a class="header-anchor" href="#solr-search" aria-label="Permalink to &quot;Solr search&quot;">​</a></h1><p><a href="https://solr.apache.org/" target="_blank" rel="noreferrer">Solr</a> is an <strong>optional</strong> full-text search engine. It is typically faster and more capable than NADA’s built-in database search, especially for large catalogs and variable-level search.</p><p>By default NADA uses database search (<code>search_provider = db</code>). After Solr is installed and indexed, switch the catalog to Solr in <a href="./site-configurations.html">Site configurations</a>.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Install Java and Solr on the server, then confirm the Solr Admin UI (usually <code>http://localhost:8983</code>). Full platform steps:</p><ul><li><a href="/nada-documentation/installation-guide/installation-solr.html">Solr full-text search — install guide</a> (Windows and Linux)</li></ul><p>Do not expose Solr’s Admin UI (<code>8983</code>) to the public internet without authentication and a firewall.</p><h2 id="connect-nada-to-solr" tabindex="-1">Connect NADA to Solr <a class="header-anchor" href="#connect-nada-to-solr" aria-label="Permalink to &quot;Connect NADA to Solr&quot;">​</a></h2><p>Edit <strong><code>application/config/solr.php</code></strong> on the NADA application server:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$config[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;solr_host&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;localhost&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$config[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;solr_port&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;8983&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$config[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;solr_collection&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;nada&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td><code>solr_host</code></td><td>Hostname or IP of the Solr server</td></tr><tr><td><code>solr_port</code></td><td>Usually <code>8983</code></td></tr><tr><td><code>solr_collection</code></td><td>Core/collection name (default <strong><code>nada</code></strong>)</td></tr></tbody></table><p>The collection name must match the core you create next.</p><h2 id="solr-admin-ui" tabindex="-1">Solr admin UI <a class="header-anchor" href="#solr-admin-ui" aria-label="Permalink to &quot;Solr admin UI&quot;">​</a></h2><p>NADA includes a Solr management page for cores, schema setup, and indexing. You do <strong>not</strong> need to hand-edit Solr’s <code>managed-schema.xml</code> for a normal install.</p><ol><li>Log in as a site administrator.</li><li>Open <strong>Site administration → Solr</strong><br> (URL pattern: <code>/index.php/admin/solr</code>).</li></ol><p>You need permission to <strong>edit configurations</strong>.</p><h3 id="recommended-order" tabindex="-1">Recommended order <a class="header-anchor" href="#recommended-order" aria-label="Permalink to &quot;Recommended order&quot;">​</a></h3><h4 id="_1-dashboard-—-ping-solr" tabindex="-1">1. Dashboard — Ping Solr <a class="header-anchor" href="#_1-dashboard-—-ping-solr" aria-label="Permalink to &quot;1. Dashboard — Ping Solr&quot;">​</a></h4><p>Use <strong>Ping SOLR</strong>. Status should show <strong>Online</strong>. The dashboard also shows Solr version and document counts when the connection works.</p><h4 id="_2-core-management-—-create-the-core" tabindex="-1">2. Core Management — create the core <a class="header-anchor" href="#_2-core-management-—-create-the-core" aria-label="Permalink to &quot;2. Core Management — create the core&quot;">​</a></h4><ol><li>Open <strong>Core Management</strong>.</li><li>Click <strong>Check Core Status</strong> for the core named in <code>solr.php</code> (default <code>nada</code>).</li><li>If the core is missing, click <strong>Create Core &quot;nada&quot;</strong> (or your configured name).</li></ol><p><strong>Alternative (Solr host command line):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> solr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/solr/bin/solr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create_core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nada</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows (from the Solr install folder)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin\\solr.cmd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create_core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nada</span></span></code></pre></div><p>Use the same name as <code>$config[&#39;solr_collection&#39;]</code>.</p><h4 id="_3-schema-management-—-initialize-the-schema" tabindex="-1">3. Schema Management — initialize the schema <a class="header-anchor" href="#_3-schema-management-—-initialize-the-schema" aria-label="Permalink to &quot;3. Schema Management — initialize the schema&quot;">​</a></h4><ol><li>Open <strong>Schema Management</strong>.</li><li>Click <strong>Setup Complete Schema</strong> (creates the field definitions NADA expects for studies, variables, and citations).</li><li>Click <strong>Validate Schema</strong>.</li></ol><p>Optional:</p><ul><li><strong>Setup Variable Fields</strong> / <strong>Setup Survey Fields</strong> — partial setups</li><li><strong>Replace existing fields</strong> — only when rebuilding schema on purpose</li></ul><p>Field definitions are defined in <code>application/config/solr.php</code> and applied through Solr’s Schema API.</p><h4 id="_4-index-the-catalog" tabindex="-1">4. Index the catalog <a class="header-anchor" href="#_4-index-the-catalog" aria-label="Permalink to &quot;4. Index the catalog&quot;">​</a></h4><p>Use <strong>Index Operations</strong> in this order for a full catalog:</p><table tabindex="0"><thead><tr><th>Action</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Index Studies</strong></td><td>Catalog entries / studies</td></tr><tr><td><strong>Index Variables</strong></td><td>Variable-level metadata (microdata)</td></tr><tr><td><strong>Index by Survey</strong></td><td>Variables for one survey at a time (useful for large catalogs)</td></tr><tr><td><strong>Index Citations</strong></td><td>Citations, if you use them</td></tr></tbody></table><p>Each screen shows progress and supports stop/resume where available. Keep the browser tab open while a job runs.</p><p><strong>Core Operations:</strong></p><ul><li><strong>Commit</strong> — flush pending index changes</li><li><strong>Clear Index</strong> — deletes all Solr documents; you must reindex afterward</li></ul><p>Compare <strong>database</strong> vs <strong>index</strong> counts on the dashboard when indexing finishes.</p><h3 id="optional-cli-indexing" tabindex="-1">Optional: CLI indexing <a class="header-anchor" href="#optional-cli-indexing" aria-label="Permalink to &quot;Optional: CLI indexing&quot;">​</a></h3><p>For large catalogs or automation, from the NADA application root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli/solr/index_studies</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli/solr/index_variables</span></span></code></pre></div><p>See <code>application/controllers/cli/Solr.php</code> for available commands and parameters.</p><h2 id="enable-solr-as-the-search-provider" tabindex="-1">Enable Solr as the search provider <a class="header-anchor" href="#enable-solr-as-the-search-provider" aria-label="Permalink to &quot;Enable Solr as the search provider&quot;">​</a></h2><p>After the core exists, the schema is set up, and indexing has completed:</p><ol><li>Open <strong>Site Administration → Settings</strong> (<a href="./site-configurations.html">Site configurations</a>).</li><li>Set <strong>Search provider</strong> to <strong>Solr</strong>.</li><li>Save.</li></ol><p>Until you switch this setting, the public catalog continues to use database search even if Solr is indexed.</p><p>Then test keyword search on the public catalog (studies and, for microdata, variables).</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>What to check</th></tr></thead><tbody><tr><td>Ping fails / Offline</td><td>Solr service running; host/port in <code>solr.php</code>; firewall; PHP can reach Solr</td></tr><tr><td>Core not found</td><td>Create core in admin UI or CLI; name matches <code>solr_collection</code></td></tr><tr><td>Schema errors</td><td>Run <strong>Setup Complete Schema</strong> again; check Solr logs; Validate Schema</td></tr><tr><td>Empty search after enabling Solr</td><td>Indexing incomplete; still on <code>db</code> provider; Clear Index then reindex</td></tr><tr><td>Indexing stalls</td><td>PHP timeouts; use Index by Survey or CLI; check <code>solr_timeout</code> in <code>solr.php</code></td></tr><tr><td>Cannot open admin Solr page</td><td>Logged in as admin with configurations <strong>edit</strong> permission</td></tr></tbody></table><p>More install-related troubleshooting: <a href="/nada-documentation/installation-guide/installation-solr.html#troubleshooting">Solr install guide</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/nada-documentation/installation-guide/installation-solr.html">Solr install (Windows &amp; Linux)</a></li><li><a href="./site-configurations.html">Site configurations</a> — search provider</li><li><a href="https://solr.apache.org/guide/" target="_blank" rel="noreferrer">Apache Solr documentation</a></li></ul>`,50)])])}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
